def solve(n, roads):
    import heapq

    # Initialize parent and rank for Union-Find
    parent = list(range(n))
    rank = [1] * n

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
        else:
            parent[v_root] = u_root
            if rank[u_root] == rank[v_root]:
                rank[u_root] += 1
        return True

    # Create a min-heap of roads
    heapq.heapify(roads)

    total_cost = 0
    road_count = 0

    while road_count < n - 1 and roads:
        u, v, w = heapq.heappop(roads)
        if union(u, v):
            total_cost += w
            road_count += 1

    if road_count < n - 1:
        return -1
    return total_cost
