def solve(n, roads):
    import heapq

    def kruskal(n, roads):
        parent = list(range(n))
        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u
        def union(u, v):
            pu, pv = find(u), find(v)
            if pu == pv:
                return False
            parent[pu] = pv
            return True

        edges = []
        for u, v, w in roads:
            edges.append((w, u, v))
        heapq.heapify(edges)

        total = 0
        count = 0
        while edges and count < n - 1:
            w, u, v = heapq.heappop(edges)
            if union(u, v):
                total += w
                count += 1
        return total if count == n - 1 else -1

    return kruskal(n, roads)
```

