def solve(n, roads):
    def kruskal(n, edges):
        parent = list(range(n))
        rank = [1] * n

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return False
            if rank[root_u] < rank[root_v]:
                parent[root_u] = root_v
            else:
                parent[root_v] = root_u
                if rank[root_u] == rank[root_v]:
                    rank[root_u] += 1
            return True

        total_cost = 0
        edges.sort(key=lambda x: x[2])
        for u, v, w in edges:
            if union(u, v):
                total_cost += w
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return -1
        return total_cost

    edge_list = []
    for u, v, w in roads:
        edge_list.append((u, v, w))
    return kruskal(n, edge_list)
